// src/components/ChordBlock.js

import React from 'react';
import { chordDiagrams } from '../data/vocabulary';

const ChordBlock = ({ sequence }) => {
  if (!sequence || sequence.length === 0) return null;

  const uniqueChords = [...new Set(sequence)];

  return (
    <div>
      {/* Блок с самими аккордами */}
      <div className="chord-names">
        {sequence.map((chord, index) => (
          <span key={index} className="chord-box">
            {chord}
          </span>
        ))}
      </div>

      {/* Блоки со схемами для каждого уникального аккорда */}
      <div className="diagrams-container">
        {uniqueChords.map(chordName => {
          const diagrams = chordDiagrams[chordName];
          if (!diagrams) return null;

          return (
            <div key={chordName} className="chord-diagram">
              {/* Название аккорда по центру */}
              <div className="chord-name">{chordName}</div>
              
              {/* Схемы аккордов в строку */}
              <div className="chord-diagram-container">
                {diagrams.map((diagram, idx) => (
                  <div key={idx} className="chord-string">
                    {/* Отрисовываем схему как одну строку */}
                    <div className="chord-fret" data-content={diagram}></div>
                  </div>
                ))}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default ChordBlock;
